import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"46 - Symbol Search","description":"","frontmatter":{},"headers":[],"relativePath":"developers/design-documentation/46-search.md","filePath":"developers/design-documentation/46-search.md"}'),d={name:"developers/design-documentation/46-search.md"};function c(i,e,r,n,h,l){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="_46-symbol-search" tabindex="-1">46 - Symbol Search <a class="header-anchor" href="#_46-symbol-search" aria-label="Permalink to &quot;46 - Symbol Search&quot;">​</a></h1><h2 id="surfaces" tabindex="-1">Surfaces <a class="header-anchor" href="#surfaces" aria-label="Permalink to &quot;Surfaces&quot;">​</a></h2><p>Tradeboard has two search contracts with different authentication and response shapes.</p><table tabindex="0"><thead><tr><th>Surface</th><th>Method and path</th><th>Auth</th><th>Purpose</th></tr></thead><tbody><tr><td>Public RESTX contract</td><td><code>POST /api/v1/search</code></td><td><code>apikey</code> in JSON</td><td>External symbol search</td></tr><tr><td>React/session suggestions</td><td><code>GET /search/api/search</code></td><td>App session</td><td>Filtered UI search</td></tr><tr><td>Expiry helper</td><td><code>GET /search/api/expiries</code></td><td>App session</td><td>Distinct expiries</td></tr><tr><td>Underlying helper</td><td><code>GET /search/api/underlyings</code></td><td>App session</td><td>Distinct option/futures underlyings</td></tr></tbody></table><p>The blueprint is <code>search_bp</code> with <code>url_prefix=&quot;/search&quot;</code>. The React <code>/search</code> page is registered before the legacy template blueprint. <code>/search/token</code> and the blueprint&#39;s <code>/search/</code> renderer remain legacy session routes; the supported first-viewport UI is <code>frontend/src/pages/Search.tsx</code>. Note that the legacy <code>/search/</code> renderer reads its query from <code>symbol</code>, not <code>q</code>. Every blueprint route is guarded by <code>@check_session_validity</code> and none carries a <code>@limiter.limit</code> decorator.</p><h2 id="restx-search" tabindex="-1">RESTX Search <a class="header-anchor" href="#restx-search" aria-label="Permalink to &quot;RESTX Search&quot;">​</a></h2><p><code>POST /api/v1/search</code> validates this JSON shape:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;apikey&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;tradeboard-api-key&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;query&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;NIFTY 26000 DEC CE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;exchange&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;NFO&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>query</code> and <code>apikey</code> are required; <code>exchange</code> is optional in <code>SearchSchema</code> (<code>restx_api/data_schemas.py</code>) and, when supplied, must be one of <code>VALID_EXCHANGES</code>. The resource carries <code>@limiter.limit(API_RATE_LIMIT)</code>, whose default in <code>restx_api/search.py</code> is <code>&quot;10 per second&quot;</code>. A schema failure returns HTTP 400 with the marshmallow messages.</p><p><code>services/search_service.py</code> verifies the key, uses the enhanced in-memory token cache when loaded and valid, and falls back to <code>database.symbol.enhanced_search_symbols()</code>.</p><p>The normalized result includes Tradeboard and broker symbol/exchange values, name, token, expiry, strike, lot size, instrument type, tick size, and option freeze quantity where available.</p><h2 id="session-search" tabindex="-1">Session Search <a class="header-anchor" href="#session-search" aria-label="Permalink to &quot;Session Search&quot;">​</a></h2><p><code>GET /search/api/search</code> accepts:</p><ul><li><code>q</code></li><li>comma-separated <code>exchange</code></li><li>comma-separated <code>instrumenttype</code></li><li><code>expiry</code></li><li><code>underlying</code></li><li><code>strike_min</code> and <code>strike_max</code></li></ul><p>At least a query or exchange is required to avoid a full-table scan; without either the endpoint returns <code>{&quot;results&quot;: [], &quot;total&quot;: 0}</code> rather than an error. Standard instruments use <code>database.symbol.enhanced_search_symbols()</code>. F&amp;O filters or an F&amp;O exchange use <code>database.token_db_enhanced.fno_search_symbols()</code>. Multi-value <code>exchange</code> and <code>instrumenttype</code> are evaluated as the union of every combination, and results are de-duplicated by <code>(symbol, exchange)</code>. The response shape is <code>{&quot;results&quot;: [...], &quot;total&quot;: &lt;count&gt;}</code>.</p><p>The expiry helper accepts optional <code>exchange</code>, <code>underlying</code> and <code>instrumenttype</code>, and returns <code>{&quot;status&quot;: &quot;success&quot;, &quot;expiries&quot;: [...]}</code>. Option-chain tools pass <code>instrumenttype=options</code>; without it the list mixes futures and options expiries, which coincide on NFO but not on MCX.</p><p>The underlying helper accepts optional <code>exchange</code> and <code>include_futures</code> (<code>1</code>, <code>true</code> or <code>yes</code>), and returns <code>{&quot;status&quot;: &quot;success&quot;, &quot;underlyings&quot;: [...]}</code>. Exchange test symbols containing <code>NSETEST</code> or <code>BSETEST</code> are filtered from its response.</p><h2 id="cache-model" tabindex="-1">Cache Model <a class="header-anchor" href="#cache-model" aria-label="Permalink to &quot;Cache Model&quot;">​</a></h2><p><code>database.token_db_enhanced</code> owns the token cache and cached F&amp;O discovery. It provides:</p><ul><li>Validity-aware general symbol search.</li><li>Indexed F&amp;O filtering.</li><li>Cached distinct expiry lookup.</li><li>Cached distinct underlying lookup, optionally including futures-only names.</li></ul><p>The search service must retain a database fallback because cache restoration happens asynchronously at startup and can be invalidated when master contracts change.</p><h2 id="consumers" tabindex="-1">Consumers <a class="header-anchor" href="#consumers" aria-label="Permalink to &quot;Consumers&quot;">​</a></h2><ul><li><code>frontend/src/pages/Search.tsx</code> uses the session suggestion endpoint.</li><li>IV, GEX, Gamma Density, OI Tracker/Profile, and related tools use the expiry/underlying helpers.</li><li>External scripts and MCP-backed API behavior use the RESTX search contract.</li></ul><h2 id="key-files" tabindex="-1">Key Files <a class="header-anchor" href="#key-files" aria-label="Permalink to &quot;Key Files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>restx_api/search.py</code></td><td>External POST contract</td></tr><tr><td><code>services/search_service.py</code></td><td>API-key verification, cache-first search, DB fallback</td></tr><tr><td><code>blueprints/search.py</code></td><td>Session search and discovery helpers</td></tr><tr><td><code>database/token_db_enhanced.py</code></td><td>Enhanced token/F&amp;O cache</td></tr><tr><td><code>database/symbol.py</code></td><td>SQLAlchemy fallback search</td></tr><tr><td><code>frontend/src/pages/Search.tsx</code></td><td>React search page</td></tr></tbody></table><p>See the <a href="./../../api-documentation/v1/data-api/search">Search API</a> for the public request contract.</p>`,26)])])}const y=t(d,[["render",c]]);export{u as __pageData,y as default};
